    (2,ca,'select get_invite()->>''code'' <> ''{code}''','true','기한이 지나면 새 링크'),
    (0,'','select invite_code from churches where id=''{a}''','________','(새 코드 읽기)'),
    (3,'','select join_church(''{code}'',''새사람'')->>''ok''','true','새 링크로 들어옴'),
